![medium](https://www.gstatic.com/codereviewagent/medium-priority.svg)

Validate the shape of the parsed `rightsOverlay` input file, record malformed entry diagnostics, and skip bad entries to ensure the package validator fails closed if the input is malformed.

```javascript
function rightsIndex(overlay, diagnostics = []) {
  const map = new Map();
  if (!overlay || typeof overlay !== 'object' || Array.isArray(overlay)) {
    diagnostics.push({
      code: "malformed_input_file",
      role: "source_figure_asset_rights_display_policy",
      path: DEFAULT_PATHS.rightsOverlayIn,
      reason: "rights_overlay_is_not_an_object",
      severity: "critical",
    });
    return map;
  }
  if (!Array.isArray(overlay.rows)) {
    diagnostics.push({
      code: "malformed_input_file",
      role: "source_figure_asset_rights_display_policy",
      path: DEFAULT_PATHS.rightsOverlayIn,
      reason: "rights_overlay_rows_is_not_an_array",
      severity: "critical",
    });
    return map;
  }
  overlay.rows.forEach((row, index) => {
    if (!row || typeof row !== 'object' || Array.isArray(row)) {
      diagnostics.push({
        code: "malformed_rights_overlay_row",
        row_index: index,
        reason: "row_is_not_an_object",
        severity: "critical",
      });
      return;
    }
    if (!row.question_key) {
      diagnostics.push({
        code: "malformed_rights_overlay_row",
        row_index: index,
        reason: "missing_question_key",
        severity: "critical",
      });
      return;
    }
    if (map.has(row.question_key)) return;
    map.set(row.question_key, {
      row,
      source_ref: {
        path: DEFAULT_PATHS.rightsOverlayIn,
        json_pointer: `/rows/${index}`,
      },
    });
  });
  return map;
}
```

<details>
<summary>References</summary>

1. When loading parsed files (such as JSON), validate the parsed file shape, record malformed entry diagnostics, skip bad entries, and pass those diagnostics into the package validator to ensure it fails closed.
2. When validating collections of data, explicitly check for and record malformed entries as structured validation failures, and skip further processing of those entries to avoid runtime property access errors.
</details>

