function vlmInputIndex(packet, diagnostics = []) {
  const map = new Map();
  if (!packet || typeof packet !== 'object' || Array.isArray(packet)) {
    diagnostics.push({
      code: "malformed_input_file",
      role: "figureasset_vlm_candidate_packet_input",
      path: DEFAULT_PATHS.vlmPacketInputIn,
      reason: "vlm_packet_input_is_not_an_object",
      severity: "critical",
    });
    return map;
  }
  if (!Array.isArray(packet.rows)) {
    diagnostics.push({
      code: "malformed_input_file",
      role: "figureasset_vlm_candidate_packet_input",
      path: DEFAULT_PATHS.vlmPacketInputIn,
      reason: "vlm_packet_input_rows_is_not_an_array",
      severity: "critical",
    });
    return map;
  }
  packet.rows.forEach((row, index) => {
    if (!row || typeof row !== 'object' || Array.isArray(row)) {
      diagnostics.push({
        code: "malformed_vlm_input_row",
        row_index: index,
        reason: "row_is_not_an_object",
        severity: "critical",
      });
      return;
    }
    if (!row.question_key) {
      diagnostics.push({
        code: "malformed_vlm_input_row",
        row_index: index,
        reason: "missing_question_key",
        severity: "critical",
      });
      return;
    }
    if (map.has(row.question_key)) return;
    map.set(row.question_key, {
      packet_role: "selected_input_row",
      path: DEFAULT_PATHS.vlmPacketInputIn,
      json_pointer: `/rows/${index}`,
      shard_id: packet?.shard?.shard_id ?? "shard-000",
      usage_priority_rank: row.usage_priority_rank ?? null,
      vlm_execution_status: packet?.vlm_execution?.status ?? null,
    });
  });
  if (Array.isArray(packet.backlog_rows)) {
    packet.backlog_rows.forEach((row, index) => {
      if (!row || typeof row !== 'object' || Array.isArray(row)) {
        diagnostics.push({
          code: "malformed_vlm_backlog_row",
          row_index: index,
          reason: "row_is_not_an_object",
          severity: "critical",
        });
        return;
      }
      if (!row.question_key) {
        diagnostics.push({
          code: "malformed_vlm_backlog_row",
          row_index: index,
          reason: "missing_question_key",
          severity: "critical",
        });
        return;
      }
      if (map.has(row.question_key)) return;
      map.set(row.question_key, {
        packet_role: "backlog_row",
        path: DEFAULT_PATHS.vlmPacketInputIn,
        json_pointer: `/backlog_rows/${index}`,
        shard_id: packet?.shard?.shard_id ?? "shard-000",
        usage_priority_rank: row.usage_priority_rank ?? null,
        vlm_execution_status: packet?.vlm_execution?.status ?? null,
      });
    });
  }
  return map;
}
