+    vlmInputPacket: safeReadOptionalJson(root, paths.vlmPacketInputIn) ?? { rows: [], backlog_rows: [] },
+    vlmOutputPacket: safeReadOptionalJson(root, paths.vlmPacketOutputIn) ?? null,
+  };
+}
+
+export function buildSourceFigureAssetCandidates(options = {}) {
+  const root = options.root ?? repoRootFromScript();
+  const paths = { ...DEFAULT_PATHS, ...(options.paths ?? {}) };
+  const generatedAt = options.generatedAt ?? DEFAULT_GENERATED_AT;
+  const diagnostics = [...asArray(options.diagnostics)];
+  const inputs = options.inputs ?? loadInputs(root, paths, diagnostics);
+  const sourceRows = validVisualRows(visualInventoryRows(inputs.visualInventory, paths, diagnostics), diagnostics);
+  const rightsByQuestionKey = rightsIndex(inputs.rightsOverlay);
+  const packetByQuestionKey = vlmInputIndex(inputs.vlmInputPacket);

